local WaxDipperMaker = {}
local PRODUCTS = {
    iron_wax_dipper = { name = "Železni potapljač za voskom", ironCost = 3, woodCost = 1, leatherCost = 1, time = 5, cost = 160, prestige = 3, happiness = 2, description = "Železni potapljač za potapljanje fitiljev v vosek." },
    bronze_wax_dipper = { name = "Bronast potapljač za voskom", bronzeCost = 3, ironCost = 1, woodCost = 1, leatherCost = 1, time = 7, cost = 390, prestige = 5, happiness = 3, description = "Bronast potapljač za enakomerne sveče." },
    silver_wax_dipper = { name = "Srebrni potapljač za voskom", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 11, cost = 940, prestige = 10, happiness = 4, description = "Srebrni potapljač za plemiške sveče." },
    gilded_wax_dipper = { name = "Pozlačeni potapljač za voskom", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 15, cost = 2030, prestige = 19, happiness = 5, description = "Pozlačeni potapljač za dvorne sveče." },
    jewel_set_wax_dipper = { name = "Draguljasti potapljač za voskom", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 19, cost = 4380, prestige = 35, happiness = 7, description = "Draguljasti potapljač za kraljevske sveče." },
    royal_sovereign_wax_dipper = { name = "Kraljevski suvereni potapljač za voskom", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 26, cost = 9400, prestige = 67, happiness = 13, description = "Suvereni potapljač z biseri za krono." },
}
local BUILDINGS = {
    waxdipper_workshop = { name = "Potapljajoča delavnica", cost = { gold = 325, wood = 175, stone = 130, iron = 8 }, upkeep = 6, qualityBonus = 5 },
    waxdipper_house = { name = "Potapljajoča hiša", cost = { gold = 1185, wood = 360, stone = 270, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_waxdipper_atelier = { name = "Mojstrski potapljajoči atelje", cost = { gold = 2975, wood = 420, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_waxdipper_palace = { name = "Suverena potapljajoča palača", cost = { gold = 12920, wood = 640, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
WaxDipperMaker.ironStock = 14; WaxDipperMaker.bronzeStock = 12; WaxDipperMaker.woodStock = 12; WaxDipperMaker.leatherStock = 10; WaxDipperMaker.silverStock = 8; WaxDipperMaker.goldStock = 6; WaxDipperMaker.jewelStock = 4; WaxDipperMaker.pearlStock = 4
WaxDipperMaker.productStock = {}; WaxDipperMaker.buildings = {}; WaxDipperMaker.maker = nil; WaxDipperMaker.activeMaking = {}; WaxDipperMaker.totalProducts = 0; WaxDipperMaker.dayTimer = 0
function WaxDipperMaker.init() WaxDipperMaker.ironStock=14; WaxDipperMaker.bronzeStock=12; WaxDipperMaker.woodStock=12; WaxDipperMaker.leatherStock=10; WaxDipperMaker.silverStock=8; WaxDipperMaker.goldStock=6; WaxDipperMaker.jewelStock=4; WaxDipperMaker.pearlStock=4; WaxDipperMaker.productStock={}; WaxDipperMaker.buildings={}; WaxDipperMaker.maker=nil; WaxDipperMaker.activeMaking={}; WaxDipperMaker.totalProducts=0; WaxDipperMaker.dayTimer=0; print("[WaxDipperMaker] Royal Wax Dipper Maker System initialized (6 products, 4 buildings)") end
function WaxDipperMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WaxDipperMaker.maker={name=n or ("Potapljač "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Potapljač najet: %s (spretnost: %d)",WaxDipperMaker.maker.name,s),"success") end; return true end
function WaxDipperMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WaxDipperMaker.build(id) local ok,e=WaxDipperMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WaxDipperMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WaxDipperMaker.getQualityBonus() local b=0; for _,bd in ipairs(WaxDipperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WaxDipperMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and WaxDipperMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and WaxDipperMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and WaxDipperMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and WaxDipperMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and WaxDipperMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WaxDipperMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WaxDipperMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WaxDipperMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WaxDipperMaker.buildings==0 then return false,"Potrebna potapljajoča delavnica" end; if not WaxDipperMaker.maker then return false,"Potreben potapljač" end; return true end
function WaxDipperMaker.make(pt,qty) qty=qty or 1; local ok,e=WaxDipperMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then WaxDipperMaker.ironStock=WaxDipperMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then WaxDipperMaker.bronzeStock=WaxDipperMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then WaxDipperMaker.woodStock=WaxDipperMaker.woodStock-d.woodCost*qty end; if d.leatherCost then WaxDipperMaker.leatherStock=WaxDipperMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then WaxDipperMaker.silverStock=WaxDipperMaker.silverStock-d.silverCost*qty end; if d.goldCost then WaxDipperMaker.goldStock=WaxDipperMaker.goldStock-d.goldCost*qty end; if d.jewelCost then WaxDipperMaker.jewelStock=WaxDipperMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then WaxDipperMaker.pearlStock=WaxDipperMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if WaxDipperMaker.maker then t=math.max(1,t-math.floor(WaxDipperMaker.maker.skill/13)) end; table.insert(WaxDipperMaker.activeMaking,{id="waxdipper_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WaxDipperMaker.completeMaking(m) local q=1.0+(WaxDipperMaker.getQualityBonus()/100); if WaxDipperMaker.maker then q=q+(WaxDipperMaker.maker.skill/140) end; q=math.min(2.5,q); WaxDipperMaker.productStock[m.productType]=(WaxDipperMaker.productStock[m.productType] or 0)+m.quantity; WaxDipperMaker.totalProducts=WaxDipperMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WaxDipperMaker.maker then WaxDipperMaker.maker.itemsMade=WaxDipperMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then WaxDipperMaker.maker.skill=math.min(100,WaxDipperMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Potapljač izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"waxdipper.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function WaxDipperMaker.update(dt) if not _G.state then return end; WaxDipperMaker.dayTimer=WaxDipperMaker.dayTimer+dt; if WaxDipperMaker.dayTimer>=30 then WaxDipperMaker.dayTimer=0; for i=#WaxDipperMaker.activeMaking,1,-1 do local m=WaxDipperMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WaxDipperMaker.completeMaking(m); table.remove(WaxDipperMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WaxDipperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WaxDipperMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WaxDipperMaker.getStats() return {ironStock=WaxDipperMaker.ironStock,bronzeStock=WaxDipperMaker.bronzeStock,woodStock=WaxDipperMaker.woodStock,leatherStock=WaxDipperMaker.leatherStock,silverStock=WaxDipperMaker.silverStock,goldStock=WaxDipperMaker.goldStock,jewelStock=WaxDipperMaker.jewelStock,pearlStock=WaxDipperMaker.pearlStock,productStock=WaxDipperMaker.productStock,numBuildings=#WaxDipperMaker.buildings,hasMaker=WaxDipperMaker.maker~=nil,makerName=WaxDipperMaker.maker and WaxDipperMaker.maker.name or "—",makerSkill=WaxDipperMaker.maker and WaxDipperMaker.maker.skill or 0,activeMaking=#WaxDipperMaker.activeMaking,totalProducts=WaxDipperMaker.totalProducts} end
return WaxDipperMaker
